INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`) VALUES (59935, 2, 1, 1, 1, 0, 'Northbound / 北行', 'Scout northward and find Mithdran Dawntracker. / 向北侦察，找到米斯德兰·晨踪者。', 'Da quilboar kidnapped da rest of da expedition and took dem north.$B$BDey said dey gonna use da expedition for some sorta sacrifice!$B$BYa gotta head north as fast as ya can ta stop dem!$B$B野猪人绑架了远征队剩下的人，把他们带去了北边。$B$B它们说要拿远征队的人当祭品！$B$B你得尽快往北赶，阻止它们！', 'Find Mithdran Dawntracker further north. / 在更北边找到米斯德兰·晨踪者。', '');
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`, `RequiredNpcOrGo1`, `RequiredNpcOrGoCount1`, `ObjectiveText1`) VALUES (59938, 2, 1, 1, 2, 0, 'Down with the Quilboar / 打倒野猪人', 'Slay Geolord Grek''og. / 击杀地卜师格雷克奥格。', 'I have discovered that the quilboar are performing a shadow ritual on a survivor from the missing expedition.$B$BThe ritual is being performed by the tribe''s leader, Geolord Grek''og.$B$BSlay Grek''og and save the survivor. Show this brute that the Horde is not to be trifled with.$B$B我发现野猪人正在对远征队的一名幸存者进行暗影仪式。$B$B主持仪式的是部落的首领，地卜师格雷克奥格。$B$B杀了格雷克奥格，救出幸存者。让这头畜生知道部落不是好惹的。', 'Meet Cork Fizzlepop to the north of the Quilboar Briarpatch. / 在野猪人荆棘地以北与科克·菲兹波普会合。', '', 151091, 1, 'Geolord Grek''og slain / 已击杀地卜师格雷克奥格');
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`, `RequiredNpcOrGo1`, `RequiredNpcOrGoCount1`, `ObjectiveText1`) VALUES (59940, 2, 1, 1, 1, 0, 'The Choppy Booster Mk. 5 / 斩切者助推器5型', 'Use the Choppy Booster Mk. 5 to scout the area. / 使用斩切者助推器5型侦察周围。', 'You''re in luck, ''cause I''m the ONE goblin who can help you find the rest of the expedition!$B$BFeast your eyes on this fancy device here. Stole it off a gnome, improved on it, and made it my own!$B$BI call it the Choppy Booster Mk. 5. Use it to find Shuja and the others.$B$B你走运了，我就是那个能帮你找到远征队其余人的地精！$B$B瞧瞧这个精巧的装置。从一个侏儒那儿偷来的，改良之后就成了我的！$B$B我管它叫斩切者助推器5型。用它去找舒佳和其他人。', '', '', 167027, 1, 'Use the Choppy Booster Mk. 5 to scout the area / 使用斩切者助推器5型侦察周围');
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`, `StartItem`, `ItemDrop1`, `ItemDropQuantity1`, `RequiredNpcOrGo1`, `RequiredNpcOrGoCount1`, `ObjectiveText1`) VALUES (59941, 2, 1, 1, 2, 0, 'Re-sizing the Situation / 重新调整局势', 'Use the Re-Sizer on 3 Wandering Boars. / 对3头游荡野猪使用缩放器。', 'I call this gadget "the Re-Sizer." It''s what I used to unshrink the Choppy Booster Mk. 5.$B$BLook, I''m gonna be honest. I got, at best, a passing understandin'' of how this thing works.$B$BThat means I''m gonna be pushing a lot of buttons to see what happens. I''m sure we''ll figure out how to upsize one of these boars. Then we''ll use it to trample those undead goons!$B$BYou hold the Re-Sizer while I fiddle with it.$B$B我管这个小玩意叫“缩放器”。我就是用它把斩切者助推器5型变回原样的。$B$B听着，我实话实说，我对它怎么运转最多也就是略知一二。$B$B也就是说我得按很多按钮看看会发生什么。我敢肯定我们能弄明白怎么把这些野猪变大。然后让它们去踩那些不死族喽啰！$B$B我摆弄的时候，你拿着缩放器。', 'Speak with Thrall. / 去和萨尔交谈。', '', 178051, 178051, 1, 156722, 3, 'Re-Sizer tested on Wandering Boars / 已对游荡野猪测试缩放器');
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`, `RequiredNpcOrGo1`, `RequiredNpcOrGoCount1`, `RequiredNpcOrGo2`, `RequiredNpcOrGoCount2`, `ObjectiveText1`, `ObjectiveText2`) VALUES (59942, 2, 1, 1, 3, 0, 'The Re-Deather / 重新亡者化', 'Slay 6 Monstrous Cadavers and Torgok. / 击杀6个巨大的尸骸和托戈克。', 'I got the perfect plan. You''re gonna ride the Choppy Booster Mk. 5 and BLAST those walkin'' cadavers from the sky!$B$BI hereby dub the Re-Sizer the "Re-Deather." We''re gonna show them where the undead belong!$B$BEr, except for OUR undead. They''re totally fine.$B$BAnyway, hop on the Choppy Booster Mk. 5 and I''ll pilot it. Once we save Wrathion, we''ll blast our way to all the other survivors!$B$B我有个完美的计划。你骑着斩切者助推器5型，从天上把那些行走的尸骸轰成渣！$B$B我在此宣布，缩放器改名叫“重新亡者化”。我们要让它们知道不死族该待在哪儿！$B$B呃，我们自己人的不死族除外。它们完全没问题。$B$B总之，跳上斩切者助推器5型，我来驾驶。救出拉希奥之后，我们就一路轰开，去救其他幸存者！', 'Find Wrathion. / 去找拉希奥。', '', 165150, 6, 162817, 1, 'Monstrous Cadavers slain / 已击杀的巨大尸骸', 'Torgok slain / 已击杀托戈克');
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`, `RequiredNpcOrGo1`, `RequiredNpcOrGoCount1`, `ObjectiveText1`) VALUES (59950, 2, 1, 1, 1, 0, 'Stocking Up on Supplies / 补充补给', 'Speak with Provisioner Jin''hake and look at his wares. / 与供给官金哈克交谈，看看他的货物。', 'Provisioner Jin''hake managed to recover some other supplies from the shipwreck.$B$BTake a look at what he has before heading out.$B$B供给官金哈克从沉船里抢救出了一些别的补给。$B$B出发前去看看他有什么。', '', '', 9167001, 1, 'Speak with Provisioner Jin''hake / 与供给官金哈克交谈');
