INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (59935, 1, 0, 0, 0, 'You made it. The quilboar went further north; we need to hurry.$B$B你到了。野猪人往更北边去了，我们得抓紧。', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (59938, 1, 0, 0, 0, 'Grek''og is dead and the survivor is safe. Well done.$B$B格雷克奥格死了，幸存者安全了。干得好。', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (59940, 1, 0, 0, 0, 'See? Fancy and fast. Now let me show you the Re-Sizer.$B$B看见没？又漂亮又快。现在让我给你看看缩放器。', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (59941, 1, 0, 0, 0, 'Thrall: I heard the goblin is making things bigger. Good. We need all the help we can get.$B$B萨尔：我听说那个地精在把东西变大。很好，我们需要一切能得到的帮助。', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (59942, 1, 0, 0, 0, 'Wrathion: You cleared a path. I owe you.$B$B拉希奥：你开出了一条路。我欠你一个人情。', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (59950, 1, 0, 0, 0, 'Supplies are scarce. Use them wisely.$B$B补给很紧张。要省着用。', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES (59938, 0, 0, 'Is it done?$B$B完成了吗？', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES (59940, 0, 0, 'Have you scouted yet?$B$B侦察过了吗？', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES (59941, 0, 0, 'Try it on the boars.$B$B在野猪身上试试。', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES (59942, 0, 0, 'Clear the cadavers!$B$B清掉那些尸骸！', 0);
