-- BEACH1C V1 (2026-11-23, Claude): Exile's Reach Horde main spine 59935 Northbound -> 59938 -> 59940 -> 59941 -> 59942 -> 59950.
-- Data from LoreWalkerTDB (12.x) re-built for AC 3.3.5. Simplified vs retail: the Choppy Booster flight/vehicle parts become talk/kill objectives (see README).
-- Safe to run twice. guids = live legal maximum + 1 (must stay below 16777215). Keep worldserver stopped.
SET @spawn_limit := 16777215;

DELETE FROM `creature` WHERE `map` = 12175 AND `Comment` LIKE 'BEACH1C %';
DELETE FROM `creature_template` WHERE `entry` IN (154327,166996,167019,149899,167021,167128,167212,151091,167027,156722,165150,162817,9167001);
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (154327,166996,167019,149899,167021,167128,167212,151091,167027,156722,165150,162817,9167001);
DELETE FROM `npc_vendor` WHERE `entry` = 9167001;
DELETE FROM `item_template` WHERE `entry` = 178051;
DELETE FROM `quest_template` WHERE `ID` IN (59935,59938,59940,59941,59942,59950);
DELETE FROM `quest_template_addon` WHERE `ID` IN (59935,59938,59940,59941,59942,59950);
DELETE FROM `quest_offer_reward` WHERE `ID` IN (59935,59938,59940,59941,59942,59950);
DELETE FROM `quest_request_items` WHERE `ID` IN (59935,59938,59940,59941,59942,59950);
DELETE FROM `creature_queststarter` WHERE `quest` IN (59935,59938,59940,59941,59942,59950);
DELETE FROM `creature_questender` WHERE `quest` IN (59935,59938,59940,59941,59942,59950);
SELECT COALESCE(MAX(`guid`), 0) INTO @g FROM `creature` WHERE `guid` < @spawn_limit;





SELECT IF(@g + 29 + 10000 < @spawn_limit, 'guid base OK', 'ABORT: no guid room, do not continue') AS guid_check, @g AS legal_max_guid;







SELECT COUNT(*) AS beach1c_creatures FROM `creature` WHERE `map` = 12175 AND `Comment` LIKE 'BEACH1C %';
SELECT MAX(`guid`) AS max_creature_guid_after, SUM(`guid` >= @spawn_limit) AS invalid_after FROM `creature`;
